export const TRICK_KEY = "toad";
export const TRICKS = ["verruca", "burrow", "parotoid", "tubercle", "bufonid"] as const;
export const HAPPY = ["loam", "knurl", "plump"] as const;
export type ToadTrickKind = (typeof TRICKS)[number];
export type ToadHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type ToadTrick = {
  kind: ToadTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type ToadHappy = {
  kind: ToadHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { loam: 1.62, knurl: 1.74, plump: 1.69 } as const;
export const BUFONID_HOLD = 18.26;
export const RELEASE_S = 1.14;
export const DUR = { bufonid: BUFONID_HOLD + RELEASE_S, verruca: 2.18, burrow: 2.46, parotoid: 2.32, tubercle: 2.38 } as const;
export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: ToadTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
    if (kind === "bufonid") return 76 + roll * 43;
  if (kind === "verruca") return 15.4 + roll * 12.8;
  if (kind === "burrow") return 24.2 + roll * 14.6;
  if (kind === "tubercle") return 18.6 + roll * 13.4;
  return justFinished ? 14.2 + roll * 10.4 : 8.1 + roll * 9.2;
}

export function pickTrick(rand?: number, musicOn?: boolean, lastKind?: ToadTrickKind | string | null) {
  if (musicOn) return "bufonid";
  const roll = rand == null ? Math.random() : rand;
  if (lastKind === "bufonid") {
    if (roll < 0.26) return "verruca";
    if (roll < 0.5) return "burrow";
    if (roll < 0.74) return "parotoid";
    return "tubercle";
  }
  if (lastKind === "verruca") {
    if (roll < 0.26) return "bufonid";
    if (roll < 0.5) return "burrow";
    if (roll < 0.74) return "parotoid";
    return "tubercle";
  }
  if (lastKind === "burrow") {
    if (roll < 0.22) return "bufonid";
    if (roll < 0.44) return "verruca";
    if (roll < 0.68) return "parotoid";
    return "tubercle";
  }
  if (roll < 0.2) return "bufonid";
  if (roll < 0.4) return "verruca";
  if (roll < 0.6) return "burrow";
  if (roll < 0.8) return "parotoid";
  return "tubercle";
}

export function happyCanStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function happyShouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function wantsThankYou(key: string | undefined | null) {
  return key === TRICK_KEY || key === "pebble";
}

export function startThankYou(
  key: string | undefined | null,
  lastKind: ToadHappyKind | string | null | undefined,
  x: number,
  facing: 1 | -1,
  flags?: TrickFlags,
) {
  if (!wantsThankYou(key)) return null;
  if (!happyCanStart(flags || { cmd: "idle" })) return null;
  const pick = pickHappy(lastKind as ToadHappyKind | null | undefined);
  return { happy: beginHappy(pick, x, facing), kind: pick };
}

export function pickHappy(lastKind?: ToadHappyKind | null, rand?: number) {
  const pool = HAPPY.filter((k) => k !== lastKind);
  const list = pool.length ? pool : [...HAPPY];
  const roll = rand == null ? Math.random() : rand;
  return list[Math.floor(roll * list.length)] || list[0];
}

export function beginHappy(kind: ToadHappyKind | string, x: number, facing: 1 | -1): ToadHappy {
  const name = (HAPPY as readonly string[]).indexOf(kind) >= 0 ? (kind as ToadHappyKind) : "loam";
  return {
    kind: name,
    happy: true,
    phase: "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: name === "loam" ? "sit" : name === "knurl" ? "play" : "sit",
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

                  export function loamPose(t) {
    const u = Math.max(0, Math.min(1, t / HAPPY_DUR.loam));
    if (u < 0.16) {
      const s = u / 0.16;
      return { lift: s * 0.018, rot: s * 0.95, dx: 0, anim: "sit" as TrickAnim };
    }
    if (u < 0.82) {
      const tick = Math.sin(t * 5.4) + 0.16 * Math.sin(t * 11.2);
      return {
        lift: 0.018 + Math.abs(tick) * 0.012,
        rot: 0.95 + tick * 1.05,
        dx: tick * 0.0009,
        anim: "sit" as TrickAnim,
      };
    }
    const s = (u - 0.82) / 0.18;
    return { lift: 0.008 * (1 - s), rot: 0.35 * (1 - s), dx: 0, anim: "idle" as TrickAnim };
  }
  export function knurlPose(t) {
    const u = Math.max(0, Math.min(1, t / HAPPY_DUR.knurl));
    if (u < 0.14) {
      const s = u / 0.14;
      return { lift: s * 0.032, rot: s * -1.65, dx: s * 0.0012, anim: "play" as TrickAnim };
    }
    if (u < 0.84) {
      const wart = Math.sin(t * 6.8) + 0.2 * Math.sin(t * 13.1);
      return {
        lift: 0.032 + Math.abs(wart) * 0.022,
        rot: -1.65 + wart * 2.55,
        dx: wart * 0.0021,
        anim: "play" as TrickAnim,
      };
    }
    const s = (u - 0.84) / 0.16;
    return { lift: 0.010 * (1 - s), rot: -0.45 * (1 - s), dx: 0, anim: "sit" as TrickAnim };
  }
  export function plumpPose(t) {
    return {
      lift: 0.008 + Math.abs(Math.sin(t * 0.48)) * 0.018,
      rot: Math.sin(t * 0.52) * 0.95,
      dx: Math.sin(t * 0.32) * 0.0012,
      anim: "sit" as TrickAnim,
    };
  }
export function stepHappy(happy: ToadHappy, dt: number, flags: TrickFlags): ToadHappy {
  if (!happy || happy.phase === "done") return happy;
  if (happyShouldAbort(flags)) {
    return { ...happy, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: ToadHappy = { ...happy, t: happy.t + Math.max(0, dt) };
  const hold = HAPPY_DUR[next.kind];
  if (next.kind === "loam") {
    const pose = loamPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "knurl") {
    const pose = knurlPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else {
    const pose = plumpPose(next.t);
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  }
  if (next.t >= hold) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}

export function sleepHoldFrame(_key?: string | null, _frameCount?: number) {
  return null;
}

export function beginTrick(kind: ToadTrickKind, x: number, facing: 1 | -1): ToadTrick {
  const anim: TrickAnim =
    kind === "bufonid"
      ? "sit"
      : kind === "verruca"
        ? "play"
        : kind === "burrow"
          ? "sit"
          : kind === "parotoid"
            ? "sit"
            : kind === "tubercle"
              ? "walk"
              : "sit";
  return {
    kind: kind,
    phase: kind === "bufonid" ? "hold" : "go",
    t: 0,
    x: x,
    lift: 0,
    rot: 0,
    anim: anim,
    facing: facing == null ? 1 : facing,
    fromX: x,
  };
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}


                    export function bufonidPose(t) {
    const breath = Math.sin(t * 0.14) + 0.04 * Math.sin(t * 0.38);
    const plump = Math.abs(Math.sin(t * 0.18));
    return {
      lift: 0.006 + plump * 0.011,
      rot: -0.18 + breath * 0.52,
    };
  }

  export function releasePose(t) {
    const u = Math.max(0, Math.min(1, t / RELEASE_S));
    return { lift: 0.006 * (1 - Math.sin(u * Math.PI * 0.5)), rot: -0.18 * (1 - u) };
  }

  export function verrucaPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.verruca));
    if (u < 0.12) {
      const s = smoothstep(u / 0.12);
      return { x: fromX, lift: s * 0.048, rot: s * -1.25 * facing, anim: "play" as TrickAnim };
    }
    if (u < 0.42) {
      const s = (u - 0.12) / 0.30;
      const jolt = Math.sin(s * Math.PI);
      return {
        x: fromX + facing * jolt * 0.028,
        lift: 0.048 + jolt * 0.052,
        rot: facing * (-1.25 + jolt * 2.85),
        anim: "play" as TrickAnim,
      };
    }
    if (u < 0.78) {
      const s = (u - 0.42) / 0.36;
      const wart = Math.sin(s * Math.PI * 2.4);
      return {
        x: fromX + facing * 0.010 + facing * wart * 0.006,
        lift: 0.014 + Math.abs(wart) * 0.012,
        rot: facing * (0.55 + wart * 1.45),
        anim: "sit" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.78) / 0.22);
    return {
      x: fromX,
      lift: 0.008 * (1 - s),
      rot: facing * (0.28 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function burrowPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.burrow));
    if (u < 0.14) {
      const s = smoothstep(u / 0.14);
      return { x: fromX, lift: s * 0.004, rot: s * 0.85 * facing, anim: "sit" as TrickAnim };
    }
    if (u < 0.70) {
      const s = (u - 0.14) / 0.56;
      const dig = Math.sin(s * Math.PI * 3.4);
      const sink = smoothstep(s);
      return {
        x: fromX + facing * dig * 0.012,
        lift: 0.004 - sink * 0.018 + Math.abs(dig) * 0.006,
        rot: facing * (0.85 + dig * 2.25 - sink * 0.55),
        anim: "sit" as TrickAnim,
      };
    }
    if (u < 0.88) {
      const s = (u - 0.70) / 0.18;
      const hold = smoothstep(s);
      return {
        x: fromX + facing * 0.004 * (1 - hold),
        lift: -0.012 + hold * 0.006,
        rot: facing * (0.35 - hold * 0.55),
        anim: "sleep" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.88) / 0.12);
    return {
      x: fromX,
      lift: -0.004 * (1 - s),
      rot: facing * (-0.12 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function parotoidPose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.parotoid));
    if (u < 0.16) {
      const s = smoothstep(u / 0.16);
      return { x: fromX, lift: s * 0.010, rot: s * -0.65 * facing, anim: "sit" as TrickAnim };
    }
    if (u < 0.74) {
      const s = (u - 0.16) / 0.58;
      const gland = Math.sin(s * Math.PI * 1.65);
      const hush = smoothstep(Math.min(1, s * 1.2));
      return {
        x: fromX + facing * gland * 0.003,
        lift: 0.010 + hush * 0.014 + Math.abs(gland) * 0.008,
        rot: facing * (-0.65 + hush * 0.95 + gland * 0.75),
        anim: "sit" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.74) / 0.26);
    return {
      x: fromX,
      lift: 0.008 * (1 - s),
      rot: facing * (-0.22 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
  export function tuberclePose(t, fromX, facing) {
    const u = Math.max(0, Math.min(1, t / DUR.tubercle));
    if (u < 0.12) {
      const s = smoothstep(u / 0.12);
      return { x: fromX, lift: s * 0.022, rot: s * 1.15 * facing, anim: "walk" as TrickAnim };
    }
    if (u < 0.78) {
      const s = (u - 0.12) / 0.66;
      const scrape = Math.sin(s * Math.PI * 2.55);
      const push = Math.sin(s * Math.PI * 1.15);
      return {
        x: fromX + facing * scrape * 0.022,
        lift: 0.022 + Math.abs(push) * 0.018 + Math.abs(scrape) * 0.010,
        rot: facing * (1.15 + push * 2.45 + scrape * 1.35),
        anim: "walk" as TrickAnim,
      };
    }
    const s = smoothstep((u - 0.78) / 0.22);
    return {
      x: fromX,
      lift: 0.010 * (1 - s),
      rot: facing * (0.35 * (1 - s)),
      anim: "sit" as TrickAnim,
    };
  }
export function stepTrick(trick: ToadTrick, dt: number, flags: TrickFlags): ToadTrick {
  if (!trick || trick.phase === "done") return trick;
  if (shouldAbort(flags) && trick.kind !== "verruca" && trick.kind !== "burrow" && trick.kind !== "parotoid" && trick.kind !== "tubercle") {
    return { ...trick, phase: "done", t: 0, lift: 0, rot: 0, anim: "idle", abort: true };
  }
  const next: ToadTrick = { ...trick, t: trick.t + Math.max(0, dt) };
  if (next.kind === "bufonid") {
    if (next.t < BUFONID_HOLD) {
      const pose = bufonidPose(next.t);
      next.phase = "hold";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    if (next.t < BUFONID_HOLD + RELEASE_S) {
      const pose = releasePose(next.t - BUFONID_HOLD);
      next.phase = "release";
      next.lift = pose.lift;
      next.rot = pose.rot;
      next.anim = "sit";
      return next;
    }
    return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  }
  const hold = DUR[next.kind];
  const u = next.t / hold;
  if (next.kind === "verruca") {
    const pose = verrucaPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "burrow") {
    const pose = burrowPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else if (next.kind === "parotoid") {
    const pose = parotoidPose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  } else {
    const pose = tuberclePose(next.t, trick.fromX != null ? trick.fromX : trick.x, trick.facing);
    next.x = pose.x;
    next.lift = pose.lift;
    next.rot = pose.rot;
    next.anim = pose.anim;
  }
  if (u >= 1) return { ...next, phase: "done", lift: 0, rot: 0, anim: "idle" };
  return next;
}
